gTZ(){return"\u0415\u0440\u0435\u0436\u0435 \u0431\u04b1\u0437\u0443\u0448\u044b"},
gTU(){return"\u0422\u04b1\u0440\u0430\u049b"},
gTX(){return"\u0411\u04b1\u043b \u2014 \u0431\u0435\u043b\u0433\u0456"},
